import math
import numbers

def most_correlated_columns(data):
    if not data or len(data) < 2:
        raise ValueError("At least two columns of data are required")

    names = list(data.keys())
    columns = list(data.values())

    n = len(columns[0])
    if n == 0:
        raise ValueError("No data")

    if any(len(col) != n for col in columns):
        raise ValueError("All columns must have the same length")

    for col in columns:
        for value in col:
            if not isinstance(value, numbers.Real):
                raise TypeError("Columns must contain only numeric values")

    cols = [[float(v) for v in col] for col in columns]
    means = [sum(col) / n for col in cols]
    centered = [[v - means[i] for v in col] for i, col in enumerate(cols)]
    sums_sq = [sum(d * d for d in col) for col in centered]

    best_pair = None
    best_abs = -1.0

    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            if sums_sq[i] == 0.0 or sums_sq[j] == 0.0:
                corr = 0.0
            else:
                cov = sum(a * b for a, b in zip(centered[i], centered[j]))
                corr = cov / math.sqrt(sums_sq[i] * sums_sq[j])

            abs_corr = abs(corr)

            if abs_corr > best_abs:
                best_abs = abs_corr
                best_pair = (names[i], names[j])

    return best_pair
