def fit_linear_regression(features, values):
    n_samples = len(features)
    n_features = len(features[0]) if n_samples else 0

    if n_samples == 0:
        return {'coefficients': [], 'intercept': 0.0}

    size = n_features + 1
    xtx = [[0.0] * size for _ in range(size)]
    xty = [0.0] * size

    for row, y in zip(features, values):
        x = [1.0] + [float(v) for v in row]
        y = float(y)
        for i in range(size):
            xty[i] += x[i] * y
            for j in range(size):
                xtx[i][j] += x[i] * x[j]

    # Solve (X^T X) beta = X^T y using Gaussian elimination
    for col in range(size):
        pivot = max(range(col, size), key=lambda r: abs(xtx[r][col]))
        if pivot != col:
            xtx[col], xtx[pivot] = xtx[pivot], xtx[col]
            xty[col], xty[pivot] = xty[pivot], xty[col]

        pivot_value = xtx[col][col]

        for row in range(col + 1, size):
            factor = xtx[row][col] / pivot_value
            if factor == 0.0:
                continue
            for c in range(col, size):
                xtx[row][c] -= factor * xtx[col][c]
            xty[row] -= factor * xty[col]

    beta = [0.0] * size
    for i in range(size - 1, -1, -1):
        total = xty[i]
        for j in range(i + 1, size):
            total -= xtx[i][j] * beta[j]
        beta[i] = total / xtx[i][i]

    return {
        'coefficients': [float(v) for v in beta[1:]],
        'intercept': float(beta[0])
    }
