import csv
import io


def normalize_numeric_columns(csv_text):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text is empty")

    rows = [row for row in reader if row]
    columns = []
    numeric_column_count = 0

    for col_index in range(len(header)):
        raw_values = [
            row[col_index] if col_index < len(row) else ""
            for row in rows
        ]

        is_numeric = bool(raw_values)
        numeric_values = []

        if is_numeric:
            for value in raw_values:
                try:
                    numeric_values.append(float(value))
                except (TypeError, ValueError):
                    is_numeric = False
                    break

        if is_numeric:
            numeric_column_count += 1
            min_value = min(numeric_values)
            max_value = max(numeric_values)

            if min_value == max_value:
                normalized = [0.0] * len(numeric_values)
            else:
                normalized = [
                    (value - min_value) / (max_value - min_value)
                    for value in numeric_values
                ]

            columns.append(normalized)
        else:
            columns.append(raw_values)

    if numeric_column_count == 0:
        raise ValueError("No numeric columns found")

    return {
        column_name: columns[index]
        for index, column_name in enumerate(header)
    }
