import math


def five_column_correlation_matrix(array):
    if not array:
        raise ValueError("Input must not be empty")

    for row in array:
        try:
            if len(row) != 5:
                raise ValueError("Each row must have exactly 5 values")
        except TypeError:
            raise ValueError("Each row must have exactly 5 values")

    n = len(array)
    columns = [[float(row[j]) for row in array] for j in range(5)]

    means = [sum(col) / n for col in columns]
    centered = [
        [value - means[j] for value in columns[j]]
        for j in range(5)
    ]
    sum_squares = [
        sum(value * value for value in centered[j])
        for j in range(5)
    ]

    result = [[0.0 for _ in range(5)] for _ in range(5)]

    for i in range(5):
        for j in range(5):
            denominator = math.sqrt(sum_squares[i] * sum_squares[j])
            if denominator == 0:
                raise ValueError("Correlation is undefined for a constant column")

            numerator = sum(centered[i][k] * centered[j][k] for k in range(n))
            result[i][j] = numerator / denominator

    return result
