def name_frequency_stats(text):
    # Extract text outside square brackets as names.
    names = []
    current = []
    in_brackets = False

    for ch in text:
        if in_brackets:
            if ch == ']':
                in_brackets = False
        else:
            if ch == '[':
                name = ''.join(current).strip()
                if name:
                    names.append(name)
                current = []
                in_brackets = True
            else:
                current.append(ch)

    name = ''.join(current).strip()
    if name:
        names.append(name)

    # Count frequencies.
    counts = {}
    for name in names:
        counts[name] = counts.get(name, 0) + 1

    values = list(counts.values())

    # Stats are undefined with no names or when all frequencies are equal.
    if not values or all(v == values[0] for v in values):
        return counts, None, None

    n = len(values)
    mean = sum(values) / n

    m2 = sum((x - mean) ** 2 for x in values) / n
    m3 = sum((x - mean) ** 3 for x in values) / n
    m4 = sum((x - mean) ** 4 for x in values) / n

    skewness = m3 / (m2 ** 1.5)
    kurtosis = m4 / (m2 * m2) - 3

    return counts, skewness, kurtosis
