def standardize_columns(data):
    result = {}

    for column, values in data.items():
        present = [v for v in values if v is not None]

        if not present:
            raise ValueError(f"Column '{column}' has no present values")

        fill_mean = sum(present) / len(present)
        filled = [fill_mean if v is None else v for v in values]

        n = len(filled)
        column_mean = sum(filled) / n
        variance = sum((x - column_mean) ** 2 for x in filled) / n
        std = variance ** 0.5

        if std == 0:
            result[column] = [0.0 for _ in filled]
        else:
            result[column] = [(x - column_mean) / std for x in filled]

    return result
