from html.parser import HTMLParser

def extract_data_table_rows(html):
    class DataTableParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.rows = []
            self.in_target = False
            self.done = False
            self.table_nesting = 0
            self.current_row = None
            self.current_cell = None

        def _finish_cell(self):
            if self.current_cell is not None:
                if self.current_row is not None:
                    self.current_row.append("".join(self.current_cell))
                self.current_cell = None

        def _finish_row(self):
            if self.current_row is not None:
                self.rows.append(self.current_row)
                self.current_row = None

        def _start_row(self):
            if self.current_cell is not None:
                self._finish_cell()
            if self.current_row is not None:
                self._finish_row()
            self.current_row = []

        def _start_cell(self):
            if self.current_row is None:
                return
            if self.current_cell is not None:
                self._finish_cell()
            self.current_cell = []

        def handle_starttag(self, tag, attrs):
            if self.done:
                return

            tag = tag.lower()

            if tag == "table":
                if not self.in_target:
                    class_value = None
                    has_class = False

                    for name, value in attrs:
                        if name == "class":
                            class_value = value
                            has_class = True
                            break

                    if has_class and class_value == "data-table":
                        self.in_target = True
                        self.table_nesting = 0
                        self.current_row = None
                        self.current_cell = None
                else:
                    self.table_nesting += 1
                return

            if not self.in_target:
                return

            if self.table_nesting == 0:
                if tag == "tr":
                    self._start_row()
                elif tag == "td":
                    self._start_cell()

        def handle_endtag(self, tag):
            if self.done or not self.in_target:
                return

            tag = tag.lower()

            if tag == "table":
                if self.table_nesting > 0:
                    self.table_nesting -= 1
                else:
                    if self.current_cell is not None:
                        self._finish_cell()
                    if self.current_row is not None:
                        self._finish_row()

                    self.in_target = False
                    self.done = True
                return

            if self.table_nesting != 0:
                return

            if tag == "td":
                if self.current_cell is not None:
                    self._finish_cell()
            elif tag == "tr":
                if self.current_cell is not None:
                    self._finish_cell()
                if self.current_row is not None:
                    self._finish_row()

        def handle_data(self, data):
            if not self.done and self.in_target and self.current_cell is not None:
                self.current_cell.append(data)

        def finish(self):
            if self.in_target:
                if self.current_cell is not None:
                    self._finish_cell()
                if self.current_row is not None:
                    self._finish_row()
                self.in_target = False
                self.done = True

    parser = DataTableParser()
    parser.feed(html)
    parser.close()
    parser.finish()

    return parser.rows
