def min_max_scale_columns(data, columns):
    result = {name: list(values) for name, values in data.items()}

    for column in columns:
        values = result[column]

        if not values:
            continue

        minimum = min(values)
        maximum = max(values)

        if minimum == maximum:
            result[column] = [0.0 for _ in values]
        else:
            result[column] = [
                (value - minimum) / (maximum - minimum)
                for value in values
            ]

    return result
