from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr"
}


class _Node:
    def __init__(self, tag=None, attrs=None, text=None):
        self.tag = tag
        self.attrs = dict(attrs) if attrs else {}
        self.children = []
        self.text = text


class _DOMParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node(tag="[document]")
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _Node(tag, attrs)
        self.stack[-1].children.append(node)
        if tag not in _VOID_TAGS:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        node = _Node(tag, attrs)
        self.stack[-1].children.append(node)

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                break

    def handle_data(self, data):
        self.stack[-1].children.append(_Node(text=data))


def _has_class(node, class_name):
    classes = node.attrs.get("class") or ""
    return class_name in classes.split()


def _find_first(node, tag, class_name=None):
    for child in node.children:
        if child.tag == tag and (class_name is None or _has_class(child, class_name)):
            return child

        found = _find_first(child, tag, class_name)
        if found is not None:
            return found

    return None


def _text(node):
    if node is None:
        return ""
    if node.tag is None:
        return node.text or ""
    return "".join(_text(child) for child in node.children)


def _iter_elements(node):
    for child in node.children:
        if child.tag is not None:
            yield child
            yield from _iter_elements(child)


def extract_article_info(html):
    parser = _DOMParser()
    parser.feed(html)
    parser.close()

    result = []

    for div in _iter_elements(parser.root):
        if div.tag == "div" and _has_class(div, "container"):
            h1 = _find_first(div, "h1")
            date = _find_first(div, "span", "date")
            author = _find_first(div, "span", "author")

            title = _text(h1).strip() if h1 is not None else "No Title"
            date_text = _text(date).strip() if date is not None else "No Date"
            author_text = _text(author).strip() if author is not None else "No Author"

            result.append((title, date_text, author_text))

    return result
