def seasonal_decomposition(values, period, model):
    values = list(values)

    if not isinstance(period, int) or isinstance(period, bool) or period <= 0:
        raise ValueError("period must be a positive integer")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    prefix = [0.0]
    for v in values:
        prefix.append(prefix[-1] + v)

    trend = [None] * n
    half = period // 2
    start = half
    end = n - half

    if period % 2 == 1:
        for t in range(start, end):
            total = prefix[t + half + 1] - prefix[t - half]
            trend[t] = total / period
    else:
        for t in range(start, end):
            left = t - half
            right = t + half
            middle_sum = prefix[right] - prefix[left + 1]
            total = (
                0.5 * values[left]
                + middle_sum
                + 0.5 * values[right]
            )
            trend[t] = total / period

    phase_sums = [0.0] * period
    phase_counts = [0] * period

    for t in range(n):
        if trend[t] is None:
            continue

        if model == "additive":
            detrended = values[t] - trend[t]
        else:
            detrended = values[t] / trend[t]

        phase = t % period
        phase_sums[phase] += detrended
        phase_counts[phase] += 1

    if any(count == 0 for count in phase_counts):
        raise ValueError("not enough data to estimate every seasonal index")

    seasonal_phase = [
        phase_sums[p] / phase_counts[p] for p in range(period)
    ]

    if model == "additive":
        mean_seasonal = sum(seasonal_phase) / period
        seasonal_phase = [s - mean_seasonal for s in seasonal_phase]
    else:
        mean_seasonal = sum(seasonal_phase) / period
        seasonal_phase = [s / mean_seasonal for s in seasonal_phase]

    seasonal = [seasonal_phase[t % period] for t in range(n)]
    residual = [None] * n

    for t in range(n):
        if trend[t] is None:
            continue

        if model == "additive":
            residual[t] = values[t] - trend[t] - seasonal[t]
        else:
            residual[t] = values[t] / (trend[t] * seasonal[t])

    return {
        "trend": trend,
        "seasonal": seasonal,
        "residual": residual,
    }
