import math


def _jacobi_eigen(matrix):
    n = len(matrix)
    if n == 0:
        return [], []

    a = [row[:] for row in matrix]
    v = [[0.0] * n for _ in range(n)]
    for i in range(n):
        v[i][i] = 1.0

    max_iter = 100 * n * n

    for _ in range(max_iter):
        off = 0.0
        p = q = 0

        for i in range(n):
            for j in range(i + 1, n):
                value = abs(a[i][j])
                if value > off:
                    off = value
                    p, q = i, j

        max_diag = max(abs(a[i][i]) for i in range(n))
        if off <= 1e-14 * max(1.0, max_diag):
            break

        app = a[p][p]
        aqq = a[q][q]
        apq = a[p][q]

        if abs(apq) < 1e-300:
            continue

        tau = (aqq - app) / (2.0 * apq)
        if tau == 0.0:
            t = 1.0
        else:
            t = math.copysign(1.0, tau) / (
                abs(tau) + math.sqrt(1.0 + tau * tau)
            )

        c = 1.0 / math.sqrt(1.0 + t * t)
        s = t * c

        for i in range(n):
            if i != p and i != q:
                aip = a[i][p]
                aiq = a[i][q]

                a[i][p] = a[p][i] = c * aip - s * aiq
                a[i][q] = a[q][i] = s * aip + c * aiq

        a[p][p] = c * c * app - 2.0 * s * c * apq + s * s * aqq
        a[q][q] = s * s * app + 2.0 * s * c * apq + c * c * aqq
        a[p][q] = a[q][p] = 0.0

        for i in range(n):
            vip = v[i][p]
            viq = v[i][q]

            v[i][p] = c * vip - s * viq
            v[i][q] = s * vip + c * viq

    eigenvalues = [a[i][i] for i in range(n)]
    return eigenvalues, v


def column_linear_regression(rows, columns, target):
    if not rows:
        raise ValueError("rows must not be empty")

    if target not in columns:
        raise ValueError("target must be one of the columns")

    n = len(rows)
    target_index = columns.index(target)

    predictor_indices = [
        i for i in range(len(columns)) if i != target_index
    ]

    y_values = [float(row[target_index]) for row in rows]
    y_mean = sum(y_values) / n

    k = len(predictor_indices)

    if k == 0:
        return [], y_mean

    x_means = []
    for index in predictor_indices:
        x_means.append(
            sum(float(row[index]) for row in rows) / n
        )

    matrix_a = [[0.0] * k for _ in range(k)]
    vector_b = [0.0] * k

    for row in rows:
        centered_x = [
            float(row[predictor_indices[j]]) - x_means[j]
            for j in range(k)
        ]
        centered_y = float(row[target_index]) - y_mean

        for i in range(k):
            xi = centered_x[i]
            vector_b[i] += xi * centered_y

            for j in range(i, k):
                matrix_a[i][j] += xi * centered_x[j]

    for i in range(k):
        for j in range(i):
            matrix_a[i][j] = matrix_a[j][i]

    eigenvalues, eigenvectors = _jacobi_eigen(matrix_a)

    max_eigenvalue = max((abs(value) for value in eigenvalues), default=0.0)
    tolerance = 1e-12 * max_eigenvalue if max_eigenvalue > 0.0 else 0.0

    coefficients = [0.0] * k

    for e in range(k):
        eigenvalue = eigenvalues[e]

        if abs(eigenvalue) > tolerance:
            eigenvector = [eigenvectors[i][e] for i in range(k)]
            dot = sum(eigenvector[i] * vector_b[i] for i in range(k))
            factor = dot / eigenvalue

            for i in range(k):
                coefficients[i] += factor * eigenvector[i]

    intercept = y_mean - sum(
        coefficients[i] * x_means[i] for i in range(k)
    )

    return coefficients, intercept
