def weather_column_summary(column, data):
    column_indices = {
        'Temperature': 1,
        'Humidity': 2,
        'Wind Speed': 3,
        'Precipitation': 4,
    }

    values = [row[column_indices[column]] for row in data]

    if not values:
        return {
            'sum': 0,
            'mean': None,
            'min': None,
            'max': None,
            'histogram': [0] * 10,
        }

    total = sum(values)
    mean = total / len(values)
    minimum = min(values)
    maximum = max(values)

    histogram = [0] * 10

    if minimum == maximum:
        # All values fall in the final closed bin [min, max].
        histogram[9] = len(values)
    else:
        bin_width = (maximum - minimum) / 10

        for value in values:
            index = int((value - minimum) / bin_width)

            if index >= 10:
                index = 9

            histogram[index] += 1

    return {
        'sum': total,
        'mean': mean,
        'min': minimum,
        'max': maximum,
        'histogram': histogram,
    }
