        published_time = article["published_time"]

        try:
            dt = datetime.fromisoformat(published_time.replace("Z", "+00:00"))
        except (AttributeError, TypeError, ValueError) as exc:
            raise ValueError("Invalid published_time") from exc

        if dt.tzinfo is None:
            raise ValueError("published_time must include a UTC offset")

        hour = dt.astimezone(tz).hour
        category = article["category"]

        hours_by_category.setdefault(category, []).append(hour)

    result = {}

    for category in sorted(hours_by_category):
        hours = hours_by_category[category]
        result[category] = {
            "count": len(hours),
            "mean": sum(hours) / len(hours),
            "min": min(hours),
            "max": max(hours),
        }

    return result
