import math

def column_correlations(data):
    columns = list(data)
    result = {x: {} for x in columns}

    if not columns:
        return result

    n = len(data[columns[0]])

    if n == 0:
        for x in columns:
            for y in columns:
                result[x][y] = 1.0 if x == y else float("nan")
        return result

    means = {x: sum(data[x]) / n for x in columns}
    centered = {x: [v - means[x] for v in data[x]] for x in columns}
    sum_squares = {x: sum(v * v for v in centered[x]) for x in columns}

    for x in columns:
        for y in columns:
            if x == y:
                result[x][y] = 1.0
            elif sum_squares[x] == 0.0 or sum_squares[y] == 0.0:
                result[x][y] = float("nan")
            else:
                numerator = sum(a * b for a, b in zip(centered[x], centered[y]))
                denominator = math.sqrt(sum_squares[x] * sum_squares[y])
                result[x][y] = numerator / denominator

    return result
