import cmath

def spectrum_magnitude_histogram(pairs):
    if not pairs:
        return ([], [])

    values = [value for _, value in pairs]
    n = len(values)

    magnitudes = []
    for k in range(n):
        coeff = 0j
        for t, value in enumerate(values):
            coeff += value * cmath.exp(-2j * math.pi * k * t / n)
        magnitudes.append(abs(coeff))

    lo = min(magnitudes)
    hi = max(magnitudes)
    counts = [0] * 10

    if hi == lo:
        counts[-1] = len(magnitudes)
        return (magnitudes, counts)

    width = (hi - lo) / 10.0

    for mag in magnitudes:
        if mag == hi:
            idx = 9
        else:
            idx = int((mag - lo) / width)
            idx = max(0, min(idx, 9))
        counts[idx] += 1

    return (magnitudes, counts)
