from collections import defaultdict

def standardize_by_group(records):
    required = ("id", "age", "income")

    for record in records:
        if not isinstance(record, dict) or any(key not in record for key in required):
            raise ValueError("Each record must contain 'id', 'age', and 'income'.")

    groups = defaultdict(list)
    for i, record in enumerate(records):
        groups[record["id"]].append(i)

    def mean_and_population_std(values):
        n = len(values)
        mean = sum(values) / n

        if all(value == values[0] for value in values):
            return mean, 0.0

        variance = sum((value - mean) ** 2 for value in values) / n
        return mean, math.sqrt(variance)

    result = [None] * len(records)

    for indices in groups.values():
        ages = [records[i]["age"] for i in indices]
        incomes = [records[i]["income"] for i in indices]

        age_mean, age_std = mean_and_population_std(ages)
        income_mean, income_std = mean_and_population_std(incomes)

        for i in indices:
            record = records[i]

            age_z = (
                0.0
                if age_std == 0.0
                else (record["age"] - age_mean) / age_std
            )
            income_z = (
                0.0
                if income_std == 0.0
                else (record["income"] - income_mean) / income_std
            )

            result[i] = {
                "id": record["id"],
                "age": float(age_z),
                "income": float(income_z),
            }

    return result
