def standardize_columns(rows, columns, features):
    if not rows:
        return []

    col_index = {name: i for i, name in enumerate(columns)}
    feature_indices = [col_index[feature] for feature in features]
    n = len(rows)

    means = {}
    stds = {}

    for idx in feature_indices:
        mean = sum(row[idx] for row in rows) / n
        variance = sum((row[idx] - mean) ** 2 for row in rows) / n
        std = variance ** 0.5

        means[idx] = mean
        stds[idx] = std

    result = []

    for row in rows:
        new_row = list(row)

        for idx in feature_indices:
            if stds[idx] == 0:
                new_row[idx] = 0.0
            else:
                new_row[idx] = (row[idx] - means[idx]) / stds[idx]

        result.append(new_row)

    return result
