import io

def fill_missing_with_column_mean(csv_text):
    if not csv_text:
        return {}

    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows:
        return {}

    header = rows[0]
    body = rows[1:]
    ncols = len(header)

    padded_body = []
    for row in body:
        if len(row) < ncols:
            row = row + [""] * (ncols - len(row))
        else:
            row = row[:ncols]
        padded_body.append(row)

    result = {}

    for col_index, column_name in enumerate(header):
        raw_values = [row[col_index] for row in padded_body]
        present = [value for value in raw_values if value != ""]

        if not present:
            result[column_name] = [None] * len(raw_values)
            continue

        try:
            numeric_values = [float(value) for value in present]
        except ValueError:
            result[column_name] = [
                None if value == "" else value
                for value in raw_values
            ]
        else:
            mean = sum(numeric_values) / len(numeric_values)
            result[column_name] = [
                mean if value == "" else float(value)
                for value in raw_values
            ]

    return result
