import math

def standardize_and_correlate(rows):
    n = len(rows)
    if n == 0:
        return [], []

    m = len(rows[0])
    data = [list(row) for row in rows]

    # Replace missing values with the mean of their column.
    for j in range(m):
        values = [rows[i][j] for i in range(n) if rows[i][j] is not None]
        mean = sum(values) / len(values) if values else 0.0
        for i in range(n):
            if data[i][j] is None:
                data[i][j] = mean

    standardized = [[0.0] * m for _ in range(n)]
    means = [0.0] * m
    stds = [0.0] * m

    # Standardize each column using population standard deviation.
    for j in range(m):
        col = [data[i][j] for i in range(n)]
        mean = sum(col) / n
        means[j] = mean

        variance = sum((x - mean) ** 2 for x in col) / n
        std = math.sqrt(variance)
        stds[j] = std

        if std != 0:
            for i in range(n):
                standardized[i][j] = (col[i] - mean) / std

    # Pearson correlation matrix.
    corr = [[0.0] * m for _ in range(m)]
    for i in range(m):
        corr[i][i] = 1.0

    for i in range(m):
        for j in range(i + 1, m):
            if stds[i] == 0.0 or stds[j] == 0.0:
                value = 0.0
            else:
                value = sum(
                    standardized[k][i] * standardized[k][j]
                    for k in range(n)
                ) / n

            corr[i][j] = value
            corr[j][i] = value

    return standardized, corr
