import math

def correlation_without_column(data, column):
    numeric = {}

    for name, values in data.items():
        if name == column:
            continue
        if not values:
            continue
        if all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in values):
            numeric[name] = values

    if not numeric:
        return None

    columns = list(numeric)
    n = len(numeric[columns[0]])

    means = {c: sum(numeric[c]) / n for c in columns}
    centered = {
        c: [v - means[c] for v in numeric[c]]
        for c in columns
    }

    def corr(x, y):
        cx, cy = centered[x], centered[y]

        numerator = sum(a * b for a, b in zip(cx, cy))
        denom_x = sum(a * a for a in cx)
        denom_y = sum(b * b for b in cy)

        if denom_x == 0 or denom_y == 0:
            return 1.0 if x == y else 0.0

        return numerator / math.sqrt(denom_x * denom_y)

    return {
        x: {y: corr(x, y) for y in columns}
        for x in columns
    }
