import math

def summarize_distribution(values, bins):
    n = len(values)

    mean = sum(values) / n

    sorted_values = sorted(values)
    mid = n // 2
    if n % 2 == 1:
        median = float(sorted_values[mid])
    else:
        median = (sorted_values[mid - 1] + sorted_values[mid]) / 2.0

    counts = {}
    first_index = {}
    for i, value in enumerate(values):
        if value not in counts:
            counts[value] = 0
            first_index[value] = i
        counts[value] += 1

    mode = min(counts, key=lambda value: (-counts[value], first_index[value]))

    variance = sum((value - mean) ** 2 for value in values) / n
    std_dev = math.sqrt(variance)

    minimum = min(values)
    maximum = max(values)
    histogram = [0] * bins

    if minimum == maximum:
        histogram[-1] = n
    else:
        width = (maximum - minimum) / bins

        for value in values:
            if value == maximum:
                index = bins - 1
            else:
                index = int((value - minimum) / width)
                index = max(0, min(index, bins - 1))

            histogram[index] += 1

    return {
        'mean': mean,
        'median': median,
        'mode': mode,
        'std_dev': std_dev,
        'histogram': histogram
    }
