def column_histogram(records, column_name):
    if not records:
        raise ValueError(f"column {column_name!r} does not exist")

    for row in records:
        if column_name not in row:
            raise ValueError(f"column {column_name!r} does not exist")

    values = [row[column_name] for row in records]

    if all(isinstance(value, str) for value in values):
        distinct = sorted(set(values))
        rank = {value: i for i, value in enumerate(distinct)}
        values = [rank[value] for value in values]

    minimum = min(values)
    maximum = max(values)
    counts = [0] * 10

    # Every value is the maximum, so place them all in the last bin.
    if minimum == maximum:
        counts[9] = len(values)
        return counts

    span = maximum - minimum

    for value in values:
        if value == maximum:
            index = 9
        else:
            index = int((value - minimum) * 10 / span)
            index = max(0, min(9, index))

        counts[index] += 1

    return counts
