def fit_linear_regression(rows, targets):
    if not rows:
        raise ValueError("rows must not be empty")
    if len(rows) != len(targets):
        raise ValueError("rows and targets must have the same length")

    n = len(rows)
    p = len(rows[0])

    for row in rows:
        if len(row) != p:
            raise ValueError("all rows must have the same length")

    xbar = [0.0] * p
    for row in rows:
        for j in range(p):
            xbar[j] += float(row[j])
    for j in range(p):
        xbar[j] /= n

    ybar = sum(float(t) for t in targets) / n

    if p == 0:
        return [], float(ybar)

    # Build the centered normal equations: A beta = b
    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for i, row in enumerate(rows):
        yc = float(targets[i]) - ybar
        xc = [float(row[j]) - xbar[j] for j in range(p)]

        for j in range(p):
            b[j] += xc[j] * yc
            for k in range(p):
                A[j][k] += xc[j] * xc[k]

    # Solve A beta = b using Gauss-Jordan elimination.
    aug = [A[i][:] + [b[i]] for i in range(p)]

    max_a = max(abs(A[i][j]) for i in range(p) for j in range(p))
    tol = max_a * 1e-12 if max_a > 0.0 else 0.0

    row = 0
    where = [-1] * p

    for col in range(p):
        if row == p:
            break

        pivot = -1
        best = 0.0
        for r in range(row, p):
            value = abs(aug[r][col])
            if value > best:
                best = value
                pivot = r

        if pivot == -1 or best <= tol:
            continue

        if pivot != row:
            aug[row], aug[pivot] = aug[pivot], aug[row]

        pivot_value = aug[row][col]
        for c in range(col, p + 1):
            aug[row][c] /= pivot_value

        for r in range(p):
            if r == row:
                continue
            factor = aug[r][col]
            if factor == 0.0:
                continue
            for c in range(col, p + 1):
                aug[r][c] -= factor * aug[row][c]

        where[col] = row
        row += 1

    beta = [0.0] * p
    for col in range(p):
        if where[col] != -1:
            beta[col] = aug[where[col]][p]

    intercept = ybar
    for j in range(p):
        intercept -= xbar[j] * beta[j]

    return beta, float(intercept)
