import json
import math


def _percentile(sorted_values, p):
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])

    pos = (n - 1) * p
    low = math.floor(pos)
    high = math.ceil(pos)

    if low == high:
        return float(sorted_values[int(pos)])

    return float(
        sorted_values[low]
        + (pos - low) * (sorted_values[high] - sorted_values[low])
    )


def _reject_json_constant(value):
    raise ValueError(f"Invalid JSON constant: {value}")


def boxplot_stats_at_path(json_data, key_path):
    try:
        data = json.loads(json_data, parse_constant=_reject_json_constant)
    except (json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError("Malformed JSON") from exc

    for key in key_path:
        if not isinstance(data, dict) or key not in data:
            raise KeyError(key)
        data = data[key]

    if not isinstance(data, str):
        raise ValueError("Value at path must be a comma-separated string of numbers")

    text = data.strip()
    if not text:
        raise ValueError("Data string is empty")

    values = []
    for part in text.split(","):
        token = part.strip()
        if token == "":
            raise ValueError("Data string contains an empty value")

        try:
            value = float(token)
        except ValueError as exc:
            raise ValueError(f"Non-numeric value: {token!r}") from exc

        if not math.isfinite(value):
            raise ValueError(f"Non-finite numeric value: {token!r}")

        values.append(value)

    values.sort()

    q1 = _percentile(values, 0.25)
    median = _percentile(values, 0.5)
    q3 = _percentile(values, 0.75)
    iqr = q3 - q1

    low_fence = q1 - 1.5 * iqr
    high_fence = q3 + 1.5 * iqr

    whisker_low = next(v for v in values if v >= low_fence)
    whisker_high = next(v for v in reversed(values) if v <= high_fence)

    outliers = [v for v in values if v < low_fence or v > high_fence]

    return {
        "q1": q1,
        "median": median,
        "q3": q3,
        "whisker_low": float(whisker_low),
        "whisker_high": float(whisker_high),
        "outliers": [float(v) for v in outliers],
    }
