def dbscan_cluster_labels(points):
    n = len(points)
    eps_sq = 3 * 3
    min_samples = 2
    labels = [None] * n

    def region_query(i):
        neighbors = []
        for j in range(n):
            dist_sq = 0.0
            for a, b in zip(points[i], points[j]):
                d = a - b
                dist_sq += d * d
            if dist_sq <= eps_sq:
                neighbors.append(j)
        return neighbors

    cluster_id = 0

    for i in range(n):
        if labels[i] is not None:
            continue

        neighbors = region_query(i)

        if len(neighbors) < min_samples:
            labels[i] = -1
            continue

        labels[i] = cluster_id
        seeds = neighbors[:]
        head = 0

        while head < len(seeds):
            j = seeds[head]
            head += 1

            if labels[j] == -1:
                labels[j] = cluster_id

            if labels[j] is None:
                labels[j] = cluster_id
                j_neighbors = region_query(j)

                if len(j_neighbors) >= min_samples:
                    for k in j_neighbors:
                        if labels[k] is None or labels[k] == -1:
                            seeds.append(k)

        cluster_id += 1

    return [-1 if label is None else label for label in labels]
