import math

def threshold_and_standardize(data):
    if not data:
        return []

    # Apply threshold and ensure output values are floats.
    result = [
        [0.0 if value < 0.5 else float(value) for value in row]
        for row in data
    ]

    n_rows = len(result)
    n_cols = len(result[0])

    for col in range(n_cols):
        column = [result[row][col] for row in range(n_rows)]

        # If all values in the column are equal, standardize to all zeros.
        if all(value == column[0] for value in column):
            for row in range(n_rows):
                result[row][col] = 0.0
            continue

        mean = sum(column) / n_rows
        variance = sum((value - mean) ** 2 for value in column) / n_rows
        std_dev = math.sqrt(variance)

        if std_dev == 0.0:
            for row in range(n_rows):
                result[row][col] = 0.0
        else:
            for row in range(n_rows):
                result[row][col] = (column[row] - mean) / std_dev

    return result
