import csv
import io


def _is_number(value):
    value = value.strip()
    if value == "":
        return False
    try:
        float(value)
        return True
    except ValueError:
        return False


def _to_number(value):
    value = value.strip()
    try:
        return int(value)
    except ValueError:
        return float(value)


def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must contain at least one CSV document")

    columns = None
    rows = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))

        try:
            header = next(reader)
        except StopIteration:
            raise ValueError("CSV document is missing a header row")

        if columns is None:
            columns = header

        column_index = {name: i for i, name in enumerate(header)}

        for row in reader:
            if not row:
                continue

            rows.append([
                row[column_index[col]]
                if col in column_index and column_index[col] < len(row)
                else ""
                for col in columns
            ])

    numeric_columns = [True] * len(columns)

    for row in rows:
        for i, value in enumerate(row):
            if not _is_number(value):
                numeric_columns[i] = False

    result = []

    for row in rows:
        record = {}
        for i, column in enumerate(columns):
            value = row[i]
            if numeric_columns[i]:
                value = _to_number(value)
            record[column] = value
        result.append(record)

    return result
