import math

def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = list(data.keys())

    # Apply value mapping
    transformed = {}
    for col, values in data.items():
        transformed[col] = [mapping.get(v, v) for v in values]

    result = {col: {} for col in columns}

    for a in columns:
        x = transformed[a]

        for b in columns:
            y = transformed[b]

            if a == b:
                result[a][b] = 1.0
                continue

            n = len(x)
            if n == 0:
                result[a][b] = float("nan")
                continue

            mean_x = sum(x) / n
            mean_y = sum(y) / n

            numerator = sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))
            denom_x = sum((xi - mean_x) ** 2 for xi in x)
            denom_y = sum((yi - mean_y) ** 2 for yi in y)

            denominator = math.sqrt(denom_x * denom_y)

            if denominator == 0:
                result[a][b] = float("nan")
            else:
                result[a][b] = numerator / denominator

    return result
