```python
def box_blur(image, kernel_size):
    if (
        not isinstance(kernel_size, int)
        or isinstance(kernel_size, bool)
        or kernel_size <= 0
        or kernel_size % 2 == 0
    ):
        raise ValueError("kernel_size must be a positive odd integer")

    if not image:
        return []

    height = len(image)
    width = len(image[0])

    if width == 0:
        return [[] for _ in range(height)]

    channels = len(image[0][0])
    radius = kernel_size // 2
    area = float(kernel_size * kernel_size)

    def reflect(index, length):
        if length == 1:
            return 0
        period = 2 * length - 2
        index %= period
        if index < length:
            return index
        return period - index

    result = []

    for y in range(height):
        out_row = []

        for x in range(width):
            totals = [0.0] * channels

            for dy in range(-radius, radius + 1):
                source_y = reflect(y + dy, height)
                source_row = image[source_y]

                for dx in range(-radius, radius + 1):
                    source_x = reflect(x + dx, width)
                    pixel = source_row[source_x]

                    for channel in range(channels):
                        totals[channel] += pixel[channel]

            out_row.append([total / area for total in totals])

        result.append(out_row)

    return result
