import calendar
import re

_WEEKDAYS = {
    "MON": 0,
    "TUE": 1,
    "WED": 2,
    "THU": 3,
    "FRI": 4,
    "SAT": 5,
    "SUN": 6,
}


def _add_month(year, month, delta=1):
    month_index = year * 12 + (month - 1) + delta
    new_year, new_month_index = divmod(month_index, 12)
    return new_year, new_month_index + 1


def _month_end_dates(start):
    year, month = start.year, start.month

    while True:
        day = calendar.monthrange(year, month)[1]
        yield date(year, month, day)
        year, month = _add_month(year, month)


def _quarter_end_dates(start):
    year = start.year
    first_month = None

    for month in (3, 6, 9, 12):
        day = calendar.monthrange(year, month)[1]
        candidate = date(year, month, day)
        if candidate >= start:
            first_month = month
            break

    if first_month is None:
        year += 1
        first_month = 3

    month = first_month
    day = calendar.monthrange(year, month)[1]
    yield date(year, month, day)

    while True:
        if month == 12:
            year += 1
            month = 3
        else:
            month += 3

        day = calendar.monthrange(year, month)[1]
        yield date(year, month, day)


def _nth_weekday(year, month, n, weekday):
    first_day = date(year, month, 1)
    offset = (weekday - first_day.weekday()) % 7
    day = 1 + offset + (n - 1) * 7
    return date(year, month, day)


def _nth_weekday_dates(start, n, weekday):
    year, month = start.year, start.month
    candidate = _nth_weekday(year, month, n, weekday)

    if candidate < start:
        year, month = _add_month(year, month)

    while True:
        yield _nth_weekday(year, month, n, weekday)
        year, month = _add_month(year, month)


def forecast_schedule(start_date, freq, sales):
    if not isinstance(start_date, str) or re.fullmatch(r"\d{4}-\d{2}-\d{2}", start_date) is None:
        raise ValueError("invalid start date")

    try:
        start = date.fromisoformat(start_date)
    except ValueError:
        raise ValueError("invalid start date") from None

    if freq == "month-end":
        dates = _month_end_dates(start)
    elif freq == "quarter-end":
        dates = _quarter_end_dates(start)
    else:
        if not isinstance(freq, str):
            raise ValueError("invalid freq")

        match = re.fullmatch(r"([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)", freq.upper())
        if match is None:
            raise ValueError("invalid freq")

        n = int(match.group(1))
        weekday = _WEEKDAYS[match.group(2)]
        dates = _nth_weekday_dates(start, n, weekday)

    return [(next(dates).isoformat(), sale) for sale in sales]
