def column_covariance(columns):
    if not columns:
        raise ValueError("table has no columns")

    names = list(columns)
    n = len(columns[names[0]])

    if n == 0:
        raise ValueError("table has no rows")

    for name in names:
        col = columns[name]

        if len(col) != n:
            raise ValueError("all columns must have the same length")

        for value in col:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError(f"column {name!r} contains a non-numeric value")

    if n < 2:
        raise ValueError("at least two rows are required for sample covariance")

    means = {name: sum(columns[name]) / n for name in names}

    result = {}
    for a in names:
        result[a] = {}
        col_a = columns[a]
        mean_a = means[a]

        for b in names:
            col_b = columns[b]
            mean_b = means[b]

            covariance = sum(
                (x - mean_a) * (y - mean_b)
                for x, y in zip(col_a, col_b)
            ) / (n - 1)

            result[a][b] = covariance

    return result
