def cluster_point_indices(points, n_clusters):
    n = len(points)
    if n == 0 or n_clusters <= 0:
        return []
    if n_clusters == 1:
        return [list(range(n))]
    if n_clusters >= n:
        return [[i] for i in range(n)]

    k = n_clusters
    dim = len(points[0])

    def dist2(a, b):
        return sum((a[d] - b[d]) ** 2 for d in range(dim))

    # Deterministic initialization: first point, then farthest points.
    centers = [list(points[0])]
    chosen = {0}

    while len(centers) < k:
        best_i = None
        best_d = -1.0

        for i, p in enumerate(points):
            if i in chosen:
                continue
            d = min(dist2(p, c) for c in centers)
            if d > best_d + 1e-12 or (
                abs(d - best_d) <= 1e-12 and (best_i is None or i < best_i)
            ):
                best_d = d
                best_i = i

        chosen.add(best_i)
        centers.append(list(points[best_i]))

    labels = [-1] * n

    for _ in range(100):
        changed = False

        # Assign points to nearest center.
        for i, p in enumerate(points):
            current = labels[i] if labels[i] != -1 else 0
            best_c = current
            best_d = dist2(p, centers[best_c])

            for c in range(k):
                if c == best_c:
                    continue

                d = dist2(p, centers[c])
                if d < best_d - 1e-12:
                    best_d = d
                    best_c = c
                elif abs(d - best_d) <= 1e-12 and labels[i] == c:
                    best_c = c

            if labels[i] != best_c:
                labels[i] = best_c
                changed = True

        # Recompute centroids.
        sums = [[0.0] * dim for _ in range(k)]
        counts = [0] * k

        for i, p in enumerate(points):
            c = labels[i]
            counts[c] += 1
            for d in range(dim):
                sums[c][d] += p[d]

        # Repair empty clusters if needed.
        if any(count == 0 for count in counts):
            candidates = [
                (dist2(p, centers[labels[i]]), i)
                for i, p in enumerate(points)
            ]
            candidates.sort(key=lambda x: (-x[0], x[1]))

            for c in range(k):
                if counts[c] == 0:
                    for _, i in candidates:
                        old = labels[i]
                        if counts[old] > 1:
                            labels[i] = c
                            counts[old] -= 1
                            counts[c] += 1
                            break

            sums = [[0.0] * dim for _ in range(k)]
            counts = [0] * k

            for i, p in enumerate(points):
                c = labels[i]
                counts[c] += 1
                for d in range(dim):
                    sums[c][d] += p[d]

        new_centers = []
        for c in range(k):
            if counts[c] > 0:
                new_centers.append([
                    sums[c][d] / counts[c] for d in range(dim)
                ])
            else:
                new_centers.append(centers[c][:])

        movement = sum(
            dist2(new_centers[c], centers[c]) for c in range(k)
        )
        centers = new_centers

        if not changed and movement < 1e-18:
            break

    # Final assignment.
    for i, p in enumerate(points):
        current = labels[i]
        best_c = current
        best_d = dist2(p, centers[best_c])

        for c in range(k):
            if c == best_c:
                continue

            d = dist2(p, centers[c])
            if d < best_d - 1e-12:
                best_d = d
                best_c = c
            elif abs(d - best_d) <= 1e-12 and labels[i] == c:
                best_c = c

        labels[i] = best_c

    groups = [[] for _ in range(k)]
    for i, c in enumerate(labels):
        groups[c].append(i)

    groups = [sorted(group) for group in groups if group]
    groups.sort(key=lambda group: group[0])
    return groups
