import csv
import io
import math
import re

_INT_RE = re.compile(r"[+-]?\d+\Z")
_NUM_RE = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?\Z")


def _parse_number(value):
    text = value.strip()

    if _INT_RE.fullmatch(text):
        return int(text)

    if _NUM_RE.fullmatch(text):
        number = float(text)
        if math.isfinite(number):
            return number

    raise ValueError(f"Not numeric: {value!r}")


def sort_csv_rows(csv_text, sort_key):
    reader = csv.reader(io.StringIO(csv_text, newline=""))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column {sort_key!r} does not exist")

    if sort_key not in header:
        raise ValueError(f"Column {sort_key!r} does not exist")

    rows = list(reader)

    numeric_columns = set()

    for i in range(len(header)):
        values = [row[i] if i < len(row) else "" for row in rows]

        if values:
            try:
                for value in values:
                    _parse_number(value)
            except ValueError:
                pass
            else:
                numeric_columns.add(i)

    records = []

    for row in rows:
        record = {}

        for i, column_name in enumerate(header):
            value = row[i] if i < len(row) else ""

            if i in numeric_columns:
                record[column_name] = _parse_number(value)
            else:
                record[column_name] = value

        records.append(record)

    records.sort(key=lambda record: record[sort_key])
    return records
