```python
def kmeans_clusters(xs, ys, n_clusters):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)

    if n_clusters < 0:
        raise ValueError("n_clusters must be non-negative")
    if n_clusters == 0:
        if n == 0:
            return []
        raise ValueError("n_clusters must be positive when there are points")
    if n_clusters > n:
        raise ValueError("n_clusters cannot exceed the number of points")

    points = [(float(xs[i]), float(ys[i])) for i in range(n)]

    if n_clusters == 1:
        return [list(range(n))]
    if n_clusters == n:
        return [[i] for i in range(n)]

    def run_kmeans(initial_centroids):
        k = len(initial_centroids)
        centroids = [(float(cx), float(cy)) for cx, cy in initial_centroids]
        labels = [-1] * n

        for _ in range(200):
            # Assign each point to the nearest centroid.
            new_labels = []
            for px, py in points:
                best_k = 0
                best_d = (px - centroids[0][0]) ** 2 + (py - centroids[0][1]) ** 2
                for kk in range(1, k):
                    d = (px - centroids[kk][0]) ** 2 + (py - centroids[kk][1]) ** 2
                    if d < best_d - 1e-12:
                        best_d = d
                        best_k = kk
                new_labels.append(best_k)

            # Handle empty clusters by moving a point from an overfull cluster.
            counts = [0] * k
            for label in new_labels:
                counts[label] += 1

            for kk in range(k):
                if counts[kk] == 0:
                    best_i = -1
                    best_d = -1.0
                    best_label = -1

                    for i, (px, py) in enumerate(points):
                        label = new_labels[i]
                        if counts[label] <= 1:
                            continue

                        cx, cy = centroids[label]
                        d = (px - cx) ** 2 + (py - cy) ** 2
                        if d > best_d + 1e-12:
                            best_d = d
                            best_i = i
                            best_label = label

                    if best_i != -1:
                        new_labels[best_i] = kk
                        counts[best_label] -= 1
                        counts[kk] += 1

            # Recompute centroids.
            new_centroids = []
            for kk in range(k):
                sx = sy = 0.0
                count = 0
                for i, label in enumerate(new_labels):
                    if label == kk:
                        sx += points[i][0]
                        sy += points[i][1]
                        count += 1

                if count:
                    new_centroids.append((sx / count, sy / count))
                else:
                    new_centroids.append(centroids[kk])

            if new_labels == labels:
                centroids = new_centroids
                labels = new_labels
                break

            labels = new_labels
            centroids = new_centroids

        inertia = 0.0
        for i, (px, py) in enumerate(points):
            cx, cy = centroids[labels[i]]
            inertia += (px - cx) ** 2 + (py - cy) ** 2

        return labels, inertia

    def farthest_first(start_idx):
        centroids = [points[start_idx]]
        used = {start_idx}

        while len(centroids) < n_clusters:
            best_i = -1
            best_d = -1.0

            for i, (px, py) in enumerate(points):
                if i in used:
                    continue

                d = min(
                    (px - cx) ** 2 + (py - cy) ** 2
                    for cx, cy in centroids
                )

                if d > best_d + 1e-12:
                    best_d = d
                    best_i = i

            if best_i == -1:
                break

            centroids.append(points[best_i])
            used.add(best_i)

        return centroids

    best_labels = None
    best_inertia = float("inf")

    # Baseline initialization: first n_clusters points.
    initial = points[:n_clusters]
    labels, inertia = run_kmeans(initial)
    best_labels = labels
    best_inertia = inertia

    # Try additional deterministic farthest-first initializations.
    if n <= 50:
        start_indices = range(n)
    else:
        step = max(1, n // 20)
        start_indices = list(range(0, n, step))
        if start_indices[-1] != n - 1:
            start_indices.append(n - 1)

    for start_idx in start_indices:
        initial = farthest_first(start_idx)
        labels, inertia = run_kmeans(initial)
        if inertia < best_inertia - 1e-12:
            best_inertia = inertia
            best_labels = labels

    clusters = [[] for _ in range(n_clusters)]
    for i, label in enumerate(best_labels):
        clusters[label].append(i)

    # Fallback to ensure no empty clusters.
    for k in range(n_clusters):
        if not clusters[k]:
            j = max(range(n_clusters), key=lambda idx: len(clusters[idx]))
            if len(clusters[j]) > 1:
                clusters[k].append(clusters[j].pop())

    clusters = [sorted(c) for c in clusters if c]
    clusters.sort(key=lambda c: c[0])

    return clusters
```

