import math
import re
from collections import Counter

def tfidf_matrix(documents):
    tokenized = [
        re.findall(r'[^\W_]+', doc.lower())
        for doc in documents
    ]

    counts = [Counter(tokens) for tokens in tokenized]

    words = sorted({
        word
        for tokens in tokenized
        for word in tokens
    })

    n = len(documents)

    df = {
        word: sum(1 for count in counts if count[word] > 0)
        for word in words
    }

    idf = {
        word: math.log((1 + n) / (1 + df[word])) + 1
        for word in words
    }

    rows = []

    for count in counts:
        row = [count[word] * idf[word] for word in words]

        norm = math.sqrt(sum(value * value for value in row))
        if norm != 0:
            row = [value / norm for value in row]

        rows.append(row)

    return words, rows
