import math

def row_distance_matrix(rows):
    for row in rows:
        for value in row:
            if not isinstance(value, (int, float)):
                raise TypeError("All elements must be int or float")

    n = len(rows)
    result = [[0.0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            distance = math.sqrt(
                sum((a - b) ** 2 for a, b in zip(rows[i], rows[j]))
            )
            result[i][j] = distance
            result[j][i] = distance

    return result
