import csv
import io
import math


def _cube_root(x):
    cbrt = getattr(math, "cbrt", None)
    if cbrt is not None:
        return cbrt(x)
    return math.copysign(abs(x) ** (1.0 / 3.0), x)


def csv_cube_roots(csv_text, columns):
    requested = list(columns)
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        header = []

    data = {name: [] for name in header}

    for col in requested:
        if col not in data:
            raise KeyError(col)

    for row in reader:
        if len(row) != len(header):
            raise ValueError("row does not match header length")

        for name, value in zip(header, row):
            try:
                data[name].append(float(value))
            except (TypeError, ValueError):
                raise ValueError(
                    f"non-numeric value {value!r} in column {name!r}"
                ) from None

    roots = {
        col: [_cube_root(value) for value in data[col]]
        for col in requested
    }

    return data, roots
