def complete_row_histogram(data, bins):
    columns = list(data.keys())

    if not columns:
        return {}, None

    n_rows = len(data[columns[0]])
    cleaned = {col: [] for col in columns}
    pooled = []

    for i in range(n_rows):
        row = []
        complete = True

        for col in columns:
            value = data[col][i]
            if value is None:
                complete = False
                break
            row.append(float(value))

        if complete:
            for col, value in zip(columns, row):
                cleaned[col].append(value)
            pooled.extend(row)

    if not pooled:
        return cleaned, None

    minimum = min(pooled)
    maximum = max(pooled)

    if minimum == maximum:
        return cleaned, None

    width = (maximum - minimum) / bins
    counts = [0] * bins

    for value in pooled:
        if value == maximum:
            index = bins - 1
        else:
            index = int((value - minimum) / width)
            index = max(0, min(index, bins - 1))

        counts[index] += 1

    return cleaned, counts
