from fractions import Fraction

def filtered_regression_coefficients(rows, height, weight, columns):
    filtered = [
        row for row in rows
        if row[columns[1]] > height and row[columns[2]] < weight
    ]

    if not filtered:
        return None

    target = columns[0]
    predictors = columns[1:]
    n_features = len(predictors) + 1  # intercept + predictors

    XtX = [[Fraction(0) for _ in range(n_features)] for _ in range(n_features)]
    Xty = [Fraction(0) for _ in range(n_features)]

    for row in filtered:
        x = [Fraction(1)] + [Fraction(str(row[name])) for name in predictors]
        y = Fraction(str(row[target]))

        for i in range(n_features):
            Xty[i] += x[i] * y
            for j in range(n_features):
                XtX[i][j] += x[i] * x[j]

    # Solve the normal equations using Gauss-Jordan elimination.
    aug = [XtX[i][:] + [Xty[i]] for i in range(n_features)]

    pivot_row = 0
    pivot_cols = []

    for col in range(n_features):
        pivot = None

        for r in range(pivot_row, n_features):
            if aug[r][col] != 0:
                pivot = r
                break

        if pivot is None:
            continue

        aug[pivot_row], aug[pivot] = aug[pivot], aug[pivot_row]

        pivot_value = aug[pivot_row][col]
        for j in range(col, n_features + 1):
            aug[pivot_row][j] /= pivot_value

        for r in range(n_features):
            if r == pivot_row:
                continue

            factor = aug[r][col]
            if factor != 0:
                for j in range(col, n_features + 1):
                    aug[r][j] -= factor * aug[pivot_row][j]

        pivot_cols.append(col)
        pivot_row += 1

        if pivot_row == n_features:
            break

    beta = [Fraction(0) for _ in range(n_features)]

    for i, col in enumerate(pivot_cols):
        beta[col] = aug[i][n_features]

    result = {'const': float(beta[0])}
    for name, coef in zip(predictors, beta[1:]):
        result[name] = float(coef)

    return result
