def cluster_labels(rows):
    import math
    import random

    n = len(rows)
    if n == 0:
        return []
    m = len(rows[0])

    # Standardize each column to zero mean and unit variance.
    X = [[0.0] * m for _ in range(n)]
    for j in range(m):
        col = [rows[i][j] for i in range(n)]
        mean = sum(col) / n
        var = sum((v - mean) ** 2 for v in col) / n
        std = math.sqrt(var) if var > 0 else 0.0

        for i in range(n):
            X[i][j] = 0.0 if std == 0.0 else (rows[i][j] - mean) / std

    # Record distinct standardized points in order of first appearance.
    point_to_id = {}
    unique = []
    for p in X:
        t = tuple(p)
        if t not in point_to_id:
            point_to_id[t] = len(unique)
            unique.append(t)

    # If there are at most 3 distinct points, each distinct point is its own cluster.
    if len(unique) <= 3:
        return [point_to_id[tuple(p)] for p in X]

    k = 3

    def dist2(a, b):
        s = 0.0
        for i in range(m):
            d = a[i] - b[i]
            s += d * d
        return s

    def init_centroids(seed):
        rng = random.Random(seed)
        centroids = [X[rng.randrange(n)][:]]

        while len(centroids) < k:
            distances = []
            total = 0.0

            for x in X:
                d = min(dist2(x, c) for c in centroids)
                distances.append(d)
                total += d

            if total == 0.0:
                used = {tuple(c) for c in centroids}
                for x in X:
                    if tuple(x) not in used:
                        centroids.append(x[:])
                        break
                else:
                    centroids.append(X[0][:])
            else:
                r = rng.random() * total
                acc = 0.0
                idx = n - 1

                for i, d in enumerate(distances):
                    acc += d
                    if acc >= r:
                        idx = i
                        break

                centroids.append(X[idx][:])

        return centroids

    def run_kmeans(seed):
        centroids = init_centroids(seed)
        labels = [-1] * n

        for _ in range(300):
            changed = False

            # Assign points to nearest centroid.
            for i, x in enumerate(X):
                best_c = 0
                best_d = float("inf")

                for c, cent in enumerate(centroids):
                    d = dist2(x, cent)
                    if d < best_d:
                        best_d = d
                        best_c = c

                if labels[i] != best_c:
                    labels[i] = best_c
                    changed = True

            # Recompute centroids.
            sums = [[0.0] * m for _ in range(k)]
            counts = [0] * k

            for i, x in enumerate(X):
                c = labels[i]
                counts[c] += 1

                for j in range(m):
                    sums[c][j] += x[j]

            new_centroids = []

            for c in range(k):
                if counts[c] == 0:
                    far_i = 0
                    far_d = -1.0

                    for i, x in enumerate(X):
                        d = min(dist2(x, cent) for cent in centroids)
                        if d > far_d:
                            far_d = d
                            far_i = i

                    new_centroids.append(X[far_i][:])
                else:
                    new_centroids.append([
                        sums[c][j] / counts[c] for j in range(m)
                    ])

            centroids = new_centroids

            if not changed:
                break

        # Final assignment and inertia.
        final_labels = []
        inertia = 0.0

        for x in X:
            best_c = 0
            best_d = float("inf")

            for c, cent in enumerate(centroids):
                d = dist2(x, cent)
                if d < best_d:
                    best_d = d
                    best_c = c

            final_labels.append(best_c)
            inertia += best_d

        return final_labels, inertia

    best_labels = None
    best_inertia = float("inf")

    for seed in range(10):
        labels, inertia = run_kmeans(seed)

        if inertia < best_inertia - 1e-12:
            best_inertia = inertia
            best_labels = labels

    # Renumber clusters in order of first appearance.
    mapping = {}
    result = []

    for label in best_labels:
        if label not in mapping:
            mapping[label] = len(mapping)
        result.append(mapping[label])

    return result
```

