def normalize_columns(data):
    if not data:
        raise ValueError("data must contain at least one column")

    normalized = {}

    for column, values in data.items():
        if not all(isinstance(value, (int, float)) for value in values):
            raise ValueError(f"Column {column!r} contains non-numeric values")

        if not values:
            normalized[column] = []
            continue

        minimum = min(values)
        maximum = max(values)

        if minimum == maximum:
            normalized[column] = [0.0 for _ in values]
        else:
            span = maximum - minimum
            normalized[column] = [
                float((value - minimum) / span) for value in values
            ]

    return normalized
