```python
def fit_joined_regression(feature_rows, target_rows, features, target):
    target_by_id = {row["id"]: row for row in target_rows}

    xs = []
    ys = []

    for row in feature_rows:
        rid = row["id"]
        if rid in target_by_id:
            xs.append([1.0] + [float(row[f]) for f in features])
            ys.append(float(target_by_id[rid][target]))

    if not xs:
        raise ValueError("no ids present in both feature_rows and target_rows")

    p = len(features)
    dim = p + 1

    # Build normal equations: (X^T X) beta = X^T y
    A = [[0.0] * dim for _ in range(dim)]
    b = [0.0] * dim

    for x, y in zip(xs, ys):
        for i in range(dim):
            b[i] += x[i] * y
            for j in range(dim):
                A[i][j] += x[i] * x[j]

    beta = _solve_linear_system(A, b)

    intercept = beta[0]
    coefficients = beta[1:]

    residuals = []
    for x, y in zip(xs, ys):
        predicted = beta[0] + sum(beta[i + 1] * x[i + 1] for i in range(p))
        residuals.append(y - predicted)

    return {
        "coefficients": coefficients,
        "intercept": intercept,
        "residuals": residuals,
    }


def _solve_linear_system(A, b):
    n = len(b)
    M = [list(A[i]) + [b[i]] for i in range(n)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))

        if abs(M[pivot][col]) < 1e-12:
            raise ValueError("singular design matrix")

        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pivot_value = M[col][col]
        for j in range(col, n + 1):
            M[col][j] /= pivot_value

        for row in range(n):
            if row == col:
                continue

            factor = M[row][col]
            if factor != 0.0:
                for j in range(col, n + 1):
                    M[row][j] -= factor * M[col][j]

    return [M[i][n] for i in range(n)]
