from collections import Counter

def column_summary_stats(table, mapping, features):
    features = list(features)

    for feature in features:
        if feature not in table:
            raise ValueError(f"Feature {feature!r} is not in table")

    result = {}

    for feature in features:
        values = []

        for value in table[feature]:
            try:
                replaced = mapping.get(value, value)
            except TypeError:
                replaced = value
                for key, mapped_value in mapping.items():
                    if value == key:
                        replaced = mapped_value
                        break

            values.append(replaced)

        n = len(values)
        if n == 0:
            raise ValueError(f"Feature {feature!r} has no values")

        mean = sum(values) / n

        ordered = sorted(values)
        if n % 2 == 1:
            median = ordered[n // 2]
        else:
            median = (ordered[n // 2 - 1] + ordered[n // 2]) / 2

        counts = Counter(values)
        highest_count = max(counts.values())
        mode = min(value for value, count in counts.items() if count == highest_count)

        variance = sum((value - mean) ** 2 for value in values) / n

        result[feature] = {
            "mean": mean,
            "median": median,
            "mode": mode,
            "variance": variance,
        }

    return result
