from html.parser import HTMLParser

def extract_links(html):
    class LinkParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.links = []       # [href, [text parts]]
            self.open_links = []  # indices of currently open <a> tags

        @staticmethod
        def get_href(attrs):
            for name, value in attrs:
                if name.lower() == "href":
                    return "" if value is None else value
            return None

        def handle_starttag(self, tag, attrs):
            if tag.lower() == "a":
                idx = len(self.links)
                self.links.append([self.get_href(attrs), []])
                self.open_links.append(idx)

        def handle_startendtag(self, tag, attrs):
            if tag.lower() == "a":
                self.links.append([self.get_href(attrs), []])

        def handle_data(self, data):
            if data:
                for idx in self.open_links:
                    self.links[idx][1].append(data)

        def handle_endtag(self, tag):
            if tag.lower() == "a" and self.open_links:
                self.open_links.pop()

    parser = LinkParser()
    parser.feed(html)
    parser.close()

    return [
        ("".join(text_parts), href)
        for href, text_parts in parser.links
    ]
