```python
from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.seen_table = False
        self.in_table = False
        self.table_depth = 0
        self.headers = []
        self.rows = []
        self.row_stack = []
        self.cell_stack = []

    def _close_cell(self, cell):
        text = "".join(cell["parts"]).strip()
        if cell["tag"] == "th":
            self.headers.append(text)
        else:
            row = cell["row"]
            if row is not None:
                row["cells"].append(text)
                row["has_td"] = True

    def _close_cells_from_depth(self, depth):
        while self.cell_stack and self.cell_stack[-1]["depth"] >= depth:
            self._close_cell(self.cell_stack.pop())

    def _close_rows_from_depth(self, depth):
        while self.row_stack and self.row_stack[-1]["depth"] >= depth:
            row = self.row_stack.pop()
            if row["has_td"]:
                self.rows.append(row["cells"])

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if tag == "table":
            if not self.seen_table:
                self.seen_table = True
                self.in_table = True
                self.table_depth = 1
            elif self.in_table:
                self.table_depth += 1
            return

        if not self.in_table:
            return

        depth = self.table_depth

        if tag == "tr":
            self._close_cells_from_depth(depth)
            self._close_rows_from_depth(depth)
            self.row_stack.append({
                "depth": depth,
                "cells": [],
                "has_td": False,
            })
        elif tag in ("th", "td"):
            self._close_cells_from_depth(depth)

            row = None
            if tag == "td" and self.row_stack and self.row_stack[-1]["depth"] == depth:
                row = self.row_stack[-1]

            self.cell_stack.append({
                "tag": tag,
                "parts": [],
                "row": row,
                "depth": depth,
            })

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_data(self, data):
        if self.in_table and self.cell_stack:
            self.cell_stack[-1]["parts"].append(data)

    def handle_endtag(self, tag):
        tag = tag.lower()

        if not self.in_table:
            return

        depth = self.table_depth

        if tag in ("td", "th"):
            self._close_cells_from_depth(depth)
        elif tag == "tr":
            self._close_cells_from_depth(depth)
            self._close_rows_from_depth(depth)
        elif tag == "table":
            self._close_cells_from_depth(depth)
            self._close_rows_from_depth(depth)
            self.table_depth -= 1
            if self.table_depth == 0:
                self.in_table = False

    def finalize(self):
        if self.in_table:
            self._close_cells_from_depth(1)
            self._close_rows_from_depth(1)
            self.in_table = False
            self.table_depth = 0


def extract_first_table(html):
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()
    parser.finalize()

    if not parser.seen_table:
        raise ValueError("No table found")
    if not parser.rows:
        raise ValueError("Table has no data rows")

    return parser.headers, parser.rows
```

