    if span == 0:
        counts[-1] = len(timestamps)
    else:
        for ts in timestamps:
            if ts == max_ts:
                index = 9
            else:
                index = int(((ts - min_ts) * 10) // span)
                if index < 0:
                    index = 0
                elif index > 9:
                    index = 9
