def standardize_filtered(data, age, weight):
    if 'Age' not in data:
        raise KeyError('Age')
    if 'Weight' not in data:
        raise KeyError('Weight')

    ages = data['Age']
    weights = data['Weight']

    kept_indices = [
        i for i in range(len(ages))
        if ages[i] < age and weights[i] > weight
    ]

    if not kept_indices:
        return {column: [] for column in data}

    result = {}

    for column, values in data.items():
        kept_values = [values[i] for i in kept_indices]
        n = len(kept_values)

        if all(v == kept_values[0] for v in kept_values):
            result[column] = [0.0] * n
            continue

        mean = sum(kept_values) / n
        variance = sum((v - mean) ** 2 for v in kept_values) / n
        std_dev = variance ** 0.5

        if std_dev == 0:
            result[column] = [0.0] * n
        else:
            result[column] = [(v - mean) / std_dev for v in kept_values]

    return result
