def grayscale_histogram(data):
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise ValueError

    data = bytes(data)
    n = len(data)

    if n < 2:
        raise ValueError

    def is_ws(c):
        return c in (9, 10, 11, 12, 13, 32)  # \t \n \v \f \r space

    if data[:2] == b"P5":
        binary = True
    elif data[:2] == b"P2":
        binary = False
    else:
        raise ValueError

    i = 2
    if i >= n or not (is_ws(data[i]) or data[i] == 35):  # 35 == '#'
        raise ValueError

    def skip_comment():
        nonlocal i
        while i < n and data[i] not in (10, 13):
            i += 1

    def skip_ws_comments():
        nonlocal i
        while True:
            while i < n and is_ws(data[i]):
                i += 1
            if i < n and data[i] == 35:
                skip_comment()
            else:
                break

    def read_token():
        nonlocal i
        skip_ws_comments()
        if i >= n:
            raise ValueError
        start = i
        while i < n and not is_ws(data[i]) and data[i] != 35:
            i += 1
        if start == i:
            raise ValueError
        return data[start:i]

    def parse_uint(token):
        if not token:
            raise ValueError
        for c in token:
            if c < 48 or c > 57:
                raise ValueError
        return int(token)

    width = parse_uint(read_token())
    height = parse_uint(read_token())
    maxval = parse_uint(read_token())

    if width <= 0 or height <= 0 or maxval <= 0 or maxval > 255:
        raise ValueError

    total = width * height
    histogram = {}

    if binary:
        if i >= n:
            raise ValueError

        if data[i] == 35:
            skip_comment()
            if i >= n:
                raise ValueError
            if data[i] == 13 and i + 1 < n and data[i + 1] == 10:
                i += 2
            else:
                i += 1
        else:
            if not is_ws(data[i]):
                raise ValueError
            if data[i] == 13 and i + 1 < n and data[i + 1] == 10:
                i += 2
            else:
                i += 1

        if i + total != n:
            raise ValueError

        for pos in range(i, i + total):
            value = data[pos]
            if value > maxval:
                raise ValueError
            histogram[value] = histogram.get(value, 0) + 1

        return histogram

    remaining = total
    while remaining:
        value = parse_uint(read_token())
        if value > maxval:
            raise ValueError
        histogram[value] = histogram.get(value, 0) + 1
        remaining -= 1

    skip_ws_comments()
    if i != n:
        raise ValueError

    return histogram
