import math

def max_pairwise_distance(xs, ys):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if n < 2:
        return 0.0

    max_distance = 0.0

    for i in range(n):
        for j in range(i + 1, n):
            distance = math.hypot(xs[i] - xs[j], ys[i] - ys[j])
            if distance > max_distance:
                max_distance = distance

    return max_distance
