import math

def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    def is_numeric(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    numeric_names = []
    for name, values in table.items():
        if values and all(is_numeric(v) for v in values):
            numeric_names.append(name)

    if not numeric_names:
        raise ValueError("table has no numeric columns")

    standardized = {}
    stats = {}

    for name, values in table.items():
        if name in numeric_names:
            n = len(values)
            mean = sum(values) / n
            variance = sum((v - mean) ** 2 for v in values) / n
            std = math.sqrt(variance)

            if std == 0:
                standardized[name] = [0.0 for _ in values]
            else:
                standardized[name] = [(v - mean) / std for v in values]

            stats[name] = (mean, std)
        else:
            standardized[name] = list(values)

    k = len(numeric_names)
    corr = [[0.0] * k for _ in range(k)]

    for i, name_i in enumerate(numeric_names):
        values_i = table[name_i]
        mean_i, std_i = stats[name_i]

        for j, name_j in enumerate(numeric_names):
            values_j = table[name_j]
            mean_j, std_j = stats[name_j]

            if i == j:
                corr[i][j] = 1.0
            elif std_i == 0 or std_j == 0:
                corr[i][j] = 0.0
            else:
                n = len(values_i)
                covariance = sum(
                    (a - mean_i) * (b - mean_j)
                    for a, b in zip(values_i, values_j)
                ) / n
                corr[i][j] = covariance / (std_i * std_j)

    return standardized, corr
