from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse


class _LinkExtractor(HTMLParser):
    def __init__(self, base_url):
        super().__init__(convert_charrefs=True)
        self.base_url = base_url
        self.links = []

    def _handle_a(self, tag, attrs):
        if tag.lower() != "a":
            return

        for name, value in attrs:
            if name.lower() == "href":
                href = value if value is not None else ""

                # Leave absolute URLs unchanged; resolve relative URLs.
                if urlparse(href).scheme:
                    self.links.append(href)
                else:
                    self.links.append(urljoin(self.base_url, href))
                break

    def handle_starttag(self, tag, attrs):
        self._handle_a(tag, attrs)

    def handle_startendtag(self, tag, attrs):
        self._handle_a(tag, attrs)


def extract_page_links(html, base_url):
    parser = _LinkExtractor(base_url)
    parser.feed(html)
    parser.close()
    return parser.links
