from html.parser import HTMLParser

def extract_table_rows(html):
    class TableParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.rows = []
            self.row_stack = []    # (row_list, table_depth)
            self.cell_stack = []   # (row_list, text_buffer)
            self.table_depth = 0

        def _close_cell(self):
            if self.cell_stack:
                row, buf = self.cell_stack.pop()
                row.append("".join(buf).strip())

        def _close_current_row(self):
            if not self.row_stack:
                return
            row, _ = self.row_stack[-1]
            while self.cell_stack and self.cell_stack[-1][0] is row:
                self._close_cell()
            self.row_stack.pop()

        def handle_starttag(self, tag, attrs):
            tag = tag.lower()

            if tag == "table":
                self.table_depth += 1

            elif tag == "tr":
                while self.row_stack and self.row_stack[-1][1] >= self.table_depth:
                    self._close_current_row()

                row = []
                self.rows.append(row)
                self.row_stack.append((row, self.table_depth))

            elif tag == "td":
                if self.row_stack:
                    current_row = self.row_stack[-1][0]

                    if self.cell_stack and self.cell_stack[-1][0] is current_row:
                        self._close_cell()

                    self.cell_stack.append((current_row, []))

            elif tag == "th":
                if self.row_stack:
                    current_row = self.row_stack[-1][0]

                    if self.cell_stack and self.cell_stack[-1][0] is current_row:
                        self._close_cell()

        def handle_startendtag(self, tag, attrs):
            self.handle_starttag(tag, attrs)
            self.handle_endtag(tag)

        def handle_data(self, data):
            for _, buf in self.cell_stack:
                buf.append(data)

        def handle_endtag(self, tag):
            tag = tag.lower()

            if tag == "td":
                if self.cell_stack:
                    self._close_cell()

            elif tag == "tr":
                self._close_current_row()

            elif tag == "table":
                if self.table_depth > 0:
                    while self.row_stack and self.row_stack[-1][1] >= self.table_depth:
                        self._close_current_row()
                    self.table_depth -= 1

        def finish(self):
            while self.cell_stack:
                self._close_cell()
            self.row_stack.clear()

    parser = TableParser()
    parser.feed(html)
    parser.close()
    parser.finish()
    return parser.rows
```

